+          if (opcode == SF32LB52_HCI_OP_LE_SET_ADV_PARAM ||
+              opcode == SF32LB52_HCI_OP_LE_SET_EXT_ADV_PARAM)
+            {
+              sf32lb52_bt_adv_ipc_diag_complete(opcode);
+            }
+        }
+    }
+  else if (data[1] == BT_HCI_EVT_CMD_STATUS && param_len >= 4)
